module tb;
    logic [99:0] in;
    logic [99:0] out;

    TopModule dut (
        .in(in),
        .out(out)
    );

    initial begin
        // Test case 1: alternating bits
        in = 100'hAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA;
        #10;
        // Expected: same or reversed? 0xAA... is 101010... reversed is still 0xAA... wait, let's check.
        // Let's do a simple known pattern.

        in = 100'h0000000000000000000000001; // bit 0 is 1
        #10;
        if (out != 100'h8000000000000000000000000) begin
            $display("SELFTEST FAIL: expected bit 99 to be 1, got %h", out);
            $finish;
        end

        in = 100'h123456789ABCDEF0123456789;
        #10;
        // verify manual reverse or simple loop reference
        begin
            logic [99:0] expected;
            for (int i = 0; i < 100; i++) begin
                expected[i] = in[99-i];
            end
            if (out !== expected) begin
                $display("SELFTEST FAIL: in=%h, got=%h, expected=%h", in, out, expected);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
